    phrases: [
      { id: "p.b1-03.1", en: "We get along really well.", he: "אנחנו מסתדרים ממש טוב." },
      { id: "p.b1-03.2", en: "I owe you an apology.", he: "אני חייב לך התנצלות." },
      { id: "p.b1-03.3", en: "Let's keep in touch.", he: "בואו נשמור על קשר." },
      { id: "p.b1-03.4", en: "It was just a misunderstanding.", he: "זאת הייתה רק אי-הבנה." },
      { id: "p.b1-03.5", en: "You can always count on me.", he: "תמיד תוכל לסמוך עליי." },
      { id: "p.b1-03.6", en: "I'd rather not get involved.", he: "אני מעדיף לא להתערב." },
      { id: "p.b1-03.7", en: "They broke up last month.", he: "הם נפרדו בחודש שעבר." },
      { id: "p.b1-03.8", en: "Would you like to join us on Friday?", he: "תרצו להצטרף אלינו ביום שישי?" },
      { id: "p.b1-03.9", en: "I'll make it up to you, I promise.", he: "אני אפצה אותך, אני מבטיח." },
      { id: "p.b1-03.10", en: "Don't take it personally.", he: "אל תיקח את זה באופן אישי." },
      { id: "p.b1-03.11", en: "I really appreciate your support.", he: "אני מאוד מעריך את התמיכה שלך." }
    ],
    sentences: [
      { id: "s.b1-03.1", en: "I'm going to volunteer at the community centre next year.", he: "אני מתכוון להתנדב במרכז הקהילתי בשנה הבאה." },
      { id: "s.b1-03.2", en: "A loyal friend will support you even in hard times.", he: "חבר נאמן יתמוך בך גם בזמנים קשים." },
      { id: "s.b1-03.3", en: "If I were you, I would apologize to her tonight.", he: "אם הייתי במקומך, הייתי מתנצל בפניה הערב." },
      { id: "s.b1-03.4", en: "They argued about money, but they compromised in the end.", he: "הם התווכחו על כסף, אבל בסוף התפשרו." },
      { id: "s.b1-03.5", en: "The couple has been together for almost ten years.", he: "הזוג ביחד כבר כמעט עשר שנים." },
      { id: "s.b1-03.6", en: "Jealousy can destroy even a strong relationship.", he: "קנאה יכולה להרוס אפילו מערכת יחסים חזקה." },
      { id: "s.b1-03.7", en: "I would never gossip about a close friend.", he: "לעולם לא הייתי מרכל על חבר קרוב." },
      { id: "s.b1-03.8", en: "She is outgoing and makes new acquaintances everywhere.", he: "היא חברותית ומכירה אנשים חדשים בכל מקום." },
      { id: "s.b1-03.9", en: "We'll see each other at the gathering on Saturday evening.", he: "נתראה במפגש במוצאי שבת." },
      { id: "s.b1-03.10", en: "Our community encourages young people to feel they belong.", he: "הקהילה שלנו מעודדת צעירים להרגיש שייכים." },
      { id: "s.b1-03.11", en: "A generous attitude helps people forgive more easily.", he: "גישה נדיבה עוזרת לאנשים לסלוח ביתר קלות." }
    ],
    dialogue: {
      title: { en: "After the argument", he: "אחרי הוויכוח" },
      roles: { A: "Lior", B: "Shira" },
      lines: [
        { id: "d.b1-03.1", who: "A", en: "You look upset. Did something happen with Dana?", he: "את נראית מוטרדת. קרה משהו עם דנה?" },
        { id: "d.b1-03.2", who: "B", en: "We had a big argument yesterday. I think she's still angry.", he: "היה לנו ויכוח גדול אתמול. אני חושבת שהיא עדיין כועסת." },
        { id: "d.b1-03.3", who: "A", en: "What was it about?", he: "על מה זה היה?" },
        { id: "d.b1-03.4", who: "B", en: "She thinks I gossiped about her, but it was a misunderstanding.", he: "היא חושבת שריכלתי עליה, אבל זאת הייתה אי-הבנה." },
        { id: "d.b1-03.5", who: "A", en: "Have you tried talking to her?", he: "ניסית לדבר איתה?" },
        { id: "d.b1-03.6", who: "B", en: "Not yet. I'm afraid she won't trust me again.", he: "עדיין לא. אני חוששת שהיא לא תבטח בי שוב." },
        { id: "d.b1-03.7", who: "A", en: "If I were you, I'd call her tonight and apologize.", he: "אם הייתי במקומך, הייתי מתקשר אליה הערב ומתנצל." },
        { id: "d.b1-03.8", who: "B", en: "You're right. I'll invite her for coffee this weekend.", he: "אתה צודק. אני אזמין אותה לקפה בסוף השבוע." },
        { id: "d.b1-03.9", who: "A", en: "Good. Real friends forgive each other.", he: "יופי. חברים אמיתיים סולחים זה לזה." },
        { id: "d.b1-03.10", who: "B", en: "Thanks for the support. I really appreciate it.", he: "תודה על התמיכה. אני באמת מעריכה את זה." }
      ]
    },
    speaking: { en: "Describe a good friend: how you met, why you get along and what you are going to do together.", he: "תארו חבר טוב: איך נפגשתם, למה אתם מסתדרים ומה אתם מתכוונים לעשות יחד." },
