    dialogue: {
      title: { en: "A radio interview with a researcher", he: "ראיון רדיו עם חוקרת" },
      roles: { A: "Ron (host)", B: "Dr. Adler" },
      lines: [
        { id: "d.b2-02.1", who: "A", en: "Dr. Adler, your team announced a breakthrough last week. What exactly did you discover?", he: "דוקטור אדלר, הצוות שלך הודיע על פריצת דרך בשבוע שעבר. מה בדיוק גיליתם?" },
        { id: "d.b2-02.2", who: "B", en: "We developed an algorithm that predicts how certain cells react to new drugs.", he: "פיתחנו אלגוריתם שחוזה איך תאים מסוימים מגיבים לתרופות חדשות." },
        { id: "d.b2-02.3", who: "A", en: "How accurate is it?", he: "עד כמה הוא מדויק?" },
        { id: "d.b2-02.4", who: "B", en: "In our experiments, around ninety percent. If the data is good, the predictions are reliable.", he: "בניסויים שלנו, בסביבות תשעים אחוז. אם הנתונים טובים, התחזיות אמינות." },
        { id: "d.b2-02.5", who: "A", en: "What would happen if a hospital relied on it and it was wrong?", he: "מה היה קורה אם בית חולים היה מסתמך עליו והוא היה טועה?" },
        { id: "d.b2-02.6", who: "B", en: "That is why doctors will always make the final decision. The tool only supports them.", he: "בדיוק בשביל זה הרופאים תמיד יקבלו את ההחלטה הסופית. הכלי רק תומך בהם." },
        { id: "d.b2-02.7", who: "A", en: "Some people fear that artificial intelligence will make scientists obsolete.", he: "יש אנשים שחוששים שבינה מלאכותית תהפוך את המדענים למיושנים." },
        { id: "d.b2-02.8", who: "B", en: "If that were true, we would have stopped hiring researchers. Instead, we hired ten more.", he: "אם זה היה נכון, היינו מפסיקים להעסיק חוקרים. במקום זה, העסקנו עשרה נוספים." },
        { id: "d.b2-02.9", who: "A", en: "And cybersecurity? Patient data is sensitive.", he: "ואבטחת סייבר? נתוני מטופלים הם רגישים." },
        { id: "d.b2-02.10", who: "B", en: "Unless the data is encrypted and stored locally, we don't use it.", he: "אלא אם הנתונים מוצפנים ונשמרים מקומית, אנחנו לא משתמשים בהם." },
        { id: "d.b2-02.11", who: "A", en: "What's next for the laboratory?", he: "מה הבא בתור במעבדה?" },
        { id: "d.b2-02.12", who: "B", en: "If we get funding, we'll conduct a larger trial next spring.", he: "אם נקבל מימון, נערוך ניסוי גדול יותר באביב הבא." }
      ]
    },
    speaking: { en: "Explain a technology you use every day: how it works, what would happen if it disappeared and what risks it has.", he: "הסבירו טכנולוגיה שאתם משתמשים בה כל יום: איך היא עובדת, מה היה קורה אם היא הייתה נעלמת ואילו סיכונים יש בה." },
