    phrases: [
      { id: "p.b2-04.1", en: "It's open to interpretation.", he: "זה פתוח לפרשנות." },
      { id: "p.b2-04.2", en: "The novel was an instant bestseller.", he: "הרומן הפך לרב-מכר מיידי." },
      { id: "p.b2-04.3", en: "I couldn't put the book down.", he: "לא יכולתי להניח את הספר מהיד." },
      { id: "p.b2-04.4", en: "The painting left a deep impression on me.", he: "הציור הותיר בי רושם עמוק." },
      { id: "p.b2-04.5", en: "The melody stayed with me for days.", he: "הלחן נשאר איתי במשך ימים." },
      { id: "p.b2-04.6", en: "She has a vivid imagination.", he: "יש לה דמיון עשיר." },
      { id: "p.b2-04.7", en: "The exhibition is well worth a visit.", he: "התערוכה בהחלט שווה ביקור." },
      { id: "p.b2-04.8", en: "What does the author mean by this?", he: "למה המחבר מתכוון בזה?" },
      { id: "p.b2-04.9", en: "The ending took me completely by surprise.", he: "הסוף הפתיע אותי לחלוטין." },
      { id: "p.b2-04.10", en: "Art is a matter of taste.", he: "אמנות היא עניין של טעם." },
      { id: "p.b2-04.11", en: "The lyrics are more important than the music.", he: "המילים חשובות יותר מהמוזיקה." }
    ],
    sentences: [
      { id: "s.b2-04.1", en: "The publication of her first novel changed her life.", he: "פרסום הרומן הראשון שלה שינה את חייה." },
      { id: "s.b2-04.2", en: "The depiction of poverty in the film is painfully realistic.", he: "תיאור העוני בסרט ריאליסטי באופן מכאיב." },
      { id: "s.b2-04.3", en: "The curator's interpretation of the sculpture surprised many visitors.", he: "פרשנות האוצר לפסל הפתיעה מבקרים רבים." },
      { id: "s.b2-04.4", en: "The protagonist's loneliness is the central theme of the novel.", he: "בדידות הגיבור היא הנושא המרכזי של הרומן." },
      { id: "s.b2-04.5", en: "The composition of the symphony took the composer nearly a decade.", he: "הלחנת הסימפוניה לקחה למלחין כמעט עשור." },
      { id: "s.b2-04.6", en: "The poet uses the sea as a metaphor for memory.", he: "המשורר משתמש בים כמטפורה לזיכרון." },
      { id: "s.b2-04.7", en: "The conductor's arrival on stage was greeted with loud applause.", he: "הגעת המנצח לבימה התקבלה במחיאות כפיים רועמות." },
      { id: "s.b2-04.8", en: "Abstract art demands the active participation of the viewer.", he: "אמנות מופשטת דורשת השתתפות פעילה של הצופה." },
      { id: "s.b2-04.9", en: "The narrator's unreliability gives the story its tension.", he: "חוסר האמינות של המספר נותן לסיפור את המתח שלו." },
      { id: "s.b2-04.10", en: "The portrait reveals the sadness behind the king's smile.", he: "הדיוקן חושף את העצב שמאחורי חיוכו של המלך." },
      { id: "s.b2-04.11", en: "The playwright found inspiration in an ancient Greek tragedy.", he: "המחזאי מצא השראה בטרגדיה יוונית עתיקה." },
      { id: "s.b2-04.12", en: "The gallery's decision to show young artists was widely praised.", he: "החלטת הגלריה להציג אמנים צעירים זכתה לשבחים רבים." }
    ],
    dialogue: {
      title: { en: "At the book club", he: "במועדון הקריאה" },
      roles: { A: "Eitan", B: "Rotem" },
      lines: [
        { id: "d.b2-04.1", who: "A", en: "So, what did everyone think of the novel?", he: "אז, מה כולם חשבו על הרומן?" },
        { id: "d.b2-04.2", who: "B", en: "Honestly, I found the protagonist hard to like, but the writing is beautiful.", he: "בכנות, היה לי קשה לאהוב את הגיבור, אבל הכתיבה יפהפייה." },
        { id: "d.b2-04.3", who: "A", en: "I agree about the writing. The author's use of metaphor is remarkable.", he: "אני מסכים לגבי הכתיבה. השימוש של המחברת במטפורות מרשים." },
        { id: "d.b2-04.4", who: "B", en: "The river that keeps returning, for example. Is it a metaphor for time?", he: "הנהר שחוזר כל הזמן, למשל. זאת מטפורה לזמן?" },
        { id: "d.b2-04.5", who: "A", en: "That's one interpretation. I read it as the narrator's guilt.", he: "זאת פרשנות אחת. אני קראתי אותו כאשמה של המספר." },
        { id: "d.b2-04.6", who: "B", en: "Interesting. The theme of guilt does run through the whole book.", he: "מעניין. נושא האשמה באמת עובר לאורך כל הספר." },
        { id: "d.b2-04.7", who: "A", en: "Did you know it's being adapted for the stage by a well-known playwright?", he: "ידעת שמחזאי ידוע מעבד אותו לבימה?" },
        { id: "d.b2-04.8", who: "B", en: "Really? I wonder how they'll depict the dream scenes.", he: "באמת? מעניין איך הם יתארו את סצנות החלום." },
        { id: "d.b2-04.9", who: "A", en: "Probably with music. The author said rhythm was more important to her than plot.", he: "כנראה עם מוזיקה. המחברת אמרה שהקצב היה חשוב לה יותר מהעלילה." },
        { id: "d.b2-04.10", who: "B", en: "That explains why it reads like poetry in places.", he: "זה מסביר למה במקומות מסוימים זה נקרא כמו שירה." },
        { id: "d.b2-04.11", who: "A", en: "Shall we choose something lighter for next month?", he: "שנבחר משהו קל יותר לחודש הבא?" },
        { id: "d.b2-04.12", who: "B", en: "Yes, please. A comedy, or at least not another tragedy.", he: "כן, בבקשה. קומדיה, או לפחות לא עוד טרגדיה." }
      ]
    },
    speaking: { en: "Present a book, film, painting or piece of music you admire: describe it, explain its themes and say why it moves you.", he: "הציגו ספר, סרט, ציור או יצירה מוזיקלית שאתם מעריכים: תארו אותם, הסבירו את הנושאים שלהם ואמרו למה הם מרגשים אתכם." },
    writing: { en: "Write a formal review (150-180 words) of an exhibition, concert or novel, using nouns rather than verbs where possible.", he: "כתבו ביקורת רשמית (150-180 מילים) על תערוכה, קונצרט או רומן, תוך שימוש בשמות עצם במקום פעלים היכן שאפשר." },
    model: { id: "m.b2-04", en: "The exhibition offers a rare depiction of ... . The curator's choice of ... creates ... . Of particular interest is ... . The combination of ... and ... results in ... . Overall, ... .", he: "התערוכה מציעה תיאור נדיר של ... . בחירת האוצר ב... יוצרת ... . מעניין במיוחד הוא ... . השילוב של ... ו... מוביל ל... . בסך הכול, ... ." }
