    phrases: [
      { id: "p.b2-05.1", en: "Innocent until proven guilty.", he: "חף מפשע עד שתוכח אשמתו." },
      { id: "p.b2-05.2", en: "He denied all the charges.", he: "הוא הכחיש את כל ההאשמות." },
      { id: "p.b2-05.3", en: "The jury reached a verdict.", he: "חבר המושבעים הגיע להכרעת דין." },
      { id: "p.b2-05.4", en: "I'll take you to court.", he: "אני אתבע אותך בבית משפט." },
      { id: "p.b2-05.5", en: "She was fined for parking illegally.", he: "היא קיבלה קנס על חנייה לא חוקית." },
      { id: "p.b2-05.6", en: "Everyone is equal before the law.", he: "כולם שווים בפני החוק." },
      { id: "p.b2-05.7", en: "The case was dismissed for lack of evidence.", he: "התיק נסגר מחוסר ראיות." },
      { id: "p.b2-05.8", en: "Is that even legal?", he: "זה בכלל חוקי?" },
      { id: "p.b2-05.9", en: "The lawyer urged his client to remain silent.", he: "עורך הדין קרא ללקוח שלו לשמור על שתיקה." },
      { id: "p.b2-05.10", en: "You have the right to remain silent.", he: "יש לך זכות לשמור על שתיקה." },
      { id: "p.b2-05.11", en: "The defendant was found not guilty.", he: "הנאשם נמצא לא אשם." }
    ],
    sentences: [
      { id: "s.b2-05.1", en: "The defendant claimed that he had been at home that night.", he: "הנאשם טען שהוא היה בבית באותו לילה." },
      { id: "s.b2-05.2", en: "The witness admitted that she had not seen the man's face.", he: "העדה הודתה שלא ראתה את פניו של האיש." },
      { id: "s.b2-05.3", en: "The judge asked the witness whether she recognized the defendant.", he: "השופט שאל את העדה אם היא מזהה את הנאשם." },
      { id: "s.b2-05.4", en: "The lawyer insisted that his client was innocent of fraud.", he: "עורך הדין התעקש שלקוחו חף מפשע בכל הנוגע להונאה." },
      { id: "s.b2-05.5", en: "The police warned residents not to leave their doors unlocked.", he: "המשטרה הזהירה את התושבים לא להשאיר את הדלתות לא נעולות." },
      { id: "s.b2-05.6", en: "The company was sued for violating privacy regulations.", he: "החברה נתבעה על הפרת תקנות פרטיות." },
      { id: "s.b2-05.7", en: "The minister denied that the new legislation would limit any rights.", he: "השר הכחיש שהחקיקה החדשה תגביל זכויות כלשהן." },
      { id: "s.b2-05.8", en: "The court ruled that the ban on the protest was unconstitutional.", he: "בית המשפט פסק שהאיסור על ההפגנה אינו חוקתי." },
      { id: "s.b2-05.9", en: "After the verdict, the defendant announced that he would appeal.", he: "אחרי הכרעת הדין, הנאשם הודיע שהוא יערער." },
      { id: "s.b2-05.10", en: "Every citizen is entitled to a fair trial under the constitution.", he: "כל אזרח זכאי למשפט הוגן על פי החוקה." },
      { id: "s.b2-05.11", en: "The investigation revealed evidence of discrimination against older workers.", he: "החקירה חשפה ראיות לאפליה נגד עובדים מבוגרים." },
      { id: "s.b2-05.12", en: "The reporter said the man had been convicted of a serious crime.", he: "הכתב אמר שהאיש הורשע בפשע חמור." }
    ],
    dialogue: {
      title: { en: "Reporting from the courthouse", he: "דיווח מבית המשפט" },
      roles: { A: "Gil (news anchor)", B: "Noa (reporter)" },
      lines: [
        { id: "d.b2-05.1", who: "A", en: "Noa, you were in the courtroom this morning. What happened?", he: "נועה, היית באולם בית המשפט הבוקר. מה קרה?" },
        { id: "d.b2-05.2", who: "B", en: "The trial began with the prosecution presenting new evidence against the defendant.", he: "המשפט נפתח בכך שהתביעה הציגה ראיות חדשות נגד הנאשם." },
        { id: "d.b2-05.3", who: "A", en: "What did the defendant say?", he: "מה אמר הנאשם?" },
        { id: "d.b2-05.4", who: "B", en: "He insisted that he was innocent and claimed the documents had been forged.", he: "הוא התעקש שהוא חף מפשע וטען שהמסמכים זויפו." },
        { id: "d.b2-05.5", who: "A", en: "Did any witnesses testify?", he: "עדים כלשהם העידו?" },
        { id: "d.b2-05.6", who: "B", en: "Yes. A former employee admitted that she had signed the contracts without reading them.", he: "כן. עובדת לשעבר הודתה שחתמה על החוזים בלי לקרוא אותם." },
        { id: "d.b2-05.7", who: "A", en: "How did the judge react?", he: "איך השופט הגיב?" },
        { id: "d.b2-05.8", who: "B", en: "He warned both sides not to speak to the press and asked whether more evidence would be submitted.", he: "הוא הזהיר את שני הצדדים לא לדבר עם העיתונות ושאל אם יוגשו ראיות נוספות." },
        { id: "d.b2-05.9", who: "A", en: "Is a verdict expected soon?", he: "צפויה הכרעת דין בקרוב?" },
        { id: "d.b2-05.10", who: "B", en: "The lawyers told me that the trial would probably last another three weeks.", he: "עורכי הדין אמרו לי שהמשפט כנראה יימשך עוד שלושה שבועות." },
        { id: "d.b2-05.11", who: "A", en: "And if he is convicted of fraud?", he: "ואם הוא יורשע בהונאה?" },
        { id: "d.b2-05.12", who: "B", en: "His lawyer has already announced that they would appeal.", he: "עורך הדין שלו כבר הודיע שהם יערערו." }
      ]
    },
